        static void Require(bool value,string text){if(!value)throw new InvalidOperationException("Quick UI 9: "+text);}
        static string State(QuickWidgetLayout layout){return new JavaScriptSerializer().Serialize(layout.Items.OrderBy(i=>i.Key,StringComparer.Ordinal).Select(i=>new object[]{i.Key,i.X,i.Y,i.Columns,i.Rows,i.Hidden}).ToArray());}
        static async Task ExpandedSpacing(QuickWindow quick)
        {
            var board=quick.GridUI.Board;string saved=State(board.Layout);quick.SetExpanded(true);await Task.Delay(280);var body=board.Frames["toggles"].Body;var rows=new List<double>();
            foreach(string key in quick.GridUI.VisibleActionKeys){var item=(StackPanel)quick.GridUI.ActionItem(key);var button=quick.FindToggle(key);var label=(TextBlock)item.Children[1];double top=button.TranslatePoint(new Point(),body).Y,bottom=button.TranslatePoint(new Point(0,button.ActualHeight),body).Y,labelTop=label.TranslatePoint(new Point(),body).Y;rows.Add(Math.Round(top,1));Require(button.ActualHeight>=47&&top>=12&&labelTop-bottom>=5&&labelTop+label.ActualHeight<=body.ActualHeight-18,"expanded circles, labels and handle have separate space");}
            var starts=rows.Distinct().OrderBy(v=>v).ToArray();Require(starts.Length==3&&starts.Zip(starts.Skip(1),(a,b)=>b-a).All(d=>d>=76),"expanded rows have comfortable vertical pitch");Require(State(board.Layout)==saved&&board.DisplayLayout.Fits(),"extra expanded space does not alter saved widget positions or overlap neighbors");Program.Save(body,(int)Math.Ceiling(body.ActualWidth),(int)Math.Ceiling(body.ActualHeight),Path.Combine(AppLog.Data,"quick9-expanded-spacing.png"));quick.SetExpanded(false);await Task.Delay(240);Require(State(board.Layout)==saved&&quick.VisibleActions==4,"fold restores the original first row and layout");
        }
        internal static void Validate(List<string> checks)
        {
            string folder=Path.Combine(Path.GetTempPath(),"OneTaskBar-grid9-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"quick-layout-9.json");
            try{
                foreach(bool vertical in new[]{false,true})foreach(int length in new[]{1,2,3,4,5})foreach(double percent in new[]{0.0,25,50,100}){double width=vertical?72:72*length,height=vertical?72*length:72;var point=vertical?new Point(width/2,height*(1-percent/100)):new Point(width*percent/100,height/2);Require(PillSlider.PositionValue(width,height,point,vertical,false)==percent,"slider pointer mapping on both axes, including circular 1 x 1");}
                var model=new QuickWidgetLayout(file);Require(model.Fits()&&model.Items.Count==QuickWidgetLayout.Keys.Length,"default grid");var baseline=model.Copy();
                foreach(string key in QuickWidgetLayout.Keys)for(int c=1;c<=4;c++)for(int r=1;r<=5;r++){
                    model.Restore(baseline);model.SetHidden(key,false);model.Resize(key,c,r,false);Require(model.Fits(),"horizontal/regular layout bounds "+key);var item=model.Find(key);Require(item.Columns==(key=="media"?Math.Max(2,c):c)&&item.Rows==(QuickWidgetLayout.Slider(key)?1:key=="media"?Math.Max(2,r):r),"size contract, including media minimum 2 x 2");
                    if(QuickWidgetLayout.Slider(key)){model.Resize(key,c,r,true);Require(model.Find(key).Columns==1&&model.Find(key).Rows==r&&model.Fits(),"vertical slider contract");}
                }
                model.Restore(baseline);model.Move("manager",0,0);Require(model.Find("manager").X==0&&model.Find("manager").Y==0&&model.Fits()&&model.Find("wifi").Y>0,"drag priority displaces overlapping widgets");
                var random=new Random(900);for(int n=0;n<300;n++){string key=QuickWidgetLayout.Keys[random.Next(QuickWidgetLayout.Keys.Length)];model.SetHidden(key,false);model.Move(key,random.Next(-2,7),random.Next(0,14));model.Resize(key,random.Next(0,7),random.Next(0,8),random.Next(2)==0);Require(model.Fits(),"repeated moves/resizes must never overlap");}
                model.SetHidden("wifi",true);model.SetHidden("wifi",false);model.Resize("volume",1,5,true);Require(model.Fits()&&model.Save(),"hide/add and persist");var restored=new QuickWidgetLayout(file);Require(State(restored)==State(model),"all positions, sizes and hidden states survive reopening; before="+State(model)+"; after="+State(restored));
                model.Restore(new[]{new QuickWidgetSlot {Key="volume",X=99,Y=-9,Columns=4,Rows=5},new QuickWidgetSlot {Key="volume",Columns=2,Rows=3},new QuickWidgetSlot {Key="foreign",Columns=99,Rows=99}});Require(model.Fits()&&model.Items.Count==QuickWidgetLayout.Keys.Length&&model.Find("volume").Rows==1,"invalid/duplicate/unknown settings sanitize without dropping known items");
                model.Restore(new[]{new QuickWidgetSlot {Key="media",Columns=1,Rows=1}});Require(model.Find("media").Columns==2&&model.Find("media").Rows==2&&model.Fits(),"stored media sizes smaller than 2 x 2 migrate safely");var presentation=new QuickWidgetLayout(null,true);presentation.Resize("media",4,1,false);Require(presentation.Find("media").Rows==1&&presentation.Fits()&&!presentation.Save(),"temporary idle media row cannot be persisted as a user layout");
                string orderFile=Path.Combine(folder,"quick-toggle-order-9.json");var order=new QuickToggleOrder(orderFile);Require(order.Keys.SequenceEqual(QuickToggleOrder.Defaults)&&order.Move("wifi","mute",false),"internal toggle order starts with the actual first row and accepts a move");Require(new QuickToggleOrder(orderFile).Keys.SequenceEqual(order.Keys)&&order.Keys[0]=="wifi","internal toggle order persists independently");Require(order.Extract("awake")&&!new QuickToggleOrder(orderFile).Members.Contains("awake")&&order.Regroup("awake")&&new QuickToggleOrder(orderFile).Members.Contains("awake"),"group membership and the reverse operation survive reopening");File.WriteAllText(orderFile,"[\"bluetooth\",\"foreign\",\"bluetooth\"]");order=new QuickToggleOrder(orderFile);Require(order.Keys.Length==10&&order.Keys.Distinct().Count()==10&&order.Keys[0]=="bluetooth"&&!order.Keys.Contains("foreign"),"invalid toggle orders keep every supported toggle once");
            }finally{foreach(string p in Directory.GetFiles(folder))File.Delete(p);Directory.Delete(folder);}
            checks.Add("UI 9 validates all 20 regular widget sizes, media minimum 2 x 2 and both slider axes, collision-free movement over 300 edits, hidden-item recovery, persistence and invalid layout sanitization without changing UI 8.5 settings");
        }
